import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    p = 1
    first, last = [], []
    for _ in range(n):
        k = int(data[p])
        ws = data[p + 1:p + 1 + k]
        p += 1 + k
        first.append(ws[0])
        last.append(ws[-1])
    by = {}
    for i in range(n):
        by.setdefault(first[i], []).append(i)
    memo = {}

    def go(mask, w):
        key = (mask, w)
        if key in memo:
            return memo[key]
        best = 0
        for j in by.get(w, ()):
            if not (mask >> j) & 1:
                v = 1 + go(mask | (1 << j), last[j])
                if v > best:
                    best = v
        memo[key] = best
        return best

    print(1 + go(1, last[0]))


